import json
from copy import deepcopy

def solve_puzzle():
    houses = [1, 2, 3, 4, 5]

    categories = ["Name", "favorite drink", "favorite color", "favorite flower", "hobby"]

    domains = {
        "Name": ["Bob", "Arnold", "Peter", "Alice", "Eric"],
        "favorite drink": ["milk", "root beer", "coffee", "tea", "water"],
        "favorite color": ["blue", "green", "white", "yellow", "red"],
        "favorite flower": ["daffodils", "roses", "lilies", "tulips", "carnations"],
        "hobby": ["painting", "cooking", "photography", "gardening", "knitting"],
    }

    # Initialize assignment structure
    assignment = {h: {} for h in houses}
    used = {cat: set() for cat in categories}

    # Helper functions
    def house_of(cat, val, asg):
        for h in houses:
            if asg[h].get(cat) == val:
                return h
        return None

    def add_assignment(h, cat, val, asg, usd):
        asg[h][cat] = val
        usd[cat].add(val)

    def remove_assignment(h, cat, val, asg, usd):
        usd[cat].remove(val)
        del asg[h][cat]

    # Pre-assign from direct clues:
    # 13. The one who only drinks water is in the third house.
    # 8. The one who only drinks water is Peter.
    add_assignment(3, "favorite drink", "water", assignment, used)
    add_assignment(3, "Name", "Peter", assignment, used)
    # 15. The person who loves white is in the second house.
    add_assignment(2, "favorite color", "white", assignment, used)
    # 10. The person who loves white is the person who loves the rose bouquet.
    add_assignment(2, "favorite flower", "roses", assignment, used)

    def possible_values(h, cat, asg, usd):
        base_domain = [v for v in domains[cat] if v not in usd[cat]]

        # House-specific fixed domains
        if cat == "Name":
            # 1. Alice is not in the fourth house.
            if h == 4 and "Alice" in base_domain:
                base_domain.remove("Alice")
            # From clue 8 and 13: Peter is in house 3
            if h == 3:
                base_domain = [v for v in base_domain if v == "Peter"]
            else:
                base_domain = [v for v in base_domain if v != "Peter"]
        elif cat == "favorite drink":
            # 13. Water is in house 3
            if h == 3:
                base_domain = [v for v in base_domain if v == "water"]
            else:
                base_domain = [v for v in base_domain if v != "water"]
        elif cat == "favorite color":
            # 15. White is in the second house only
            if h == 2:
                base_domain = [v for v in base_domain if v == "white"]
            else:
                base_domain = [v for v in base_domain if v != "white"]
        elif cat == "favorite flower":
            # 10 and 15 imply roses in house 2
            if h == 2:
                base_domain = [v for v in base_domain if v == "roses"]
            else:
                base_domain = [v for v in base_domain if v != "roses"]

        # Apply intra-house equivalences to reduce domain further
        # 2 and 14. root beer <-> gardening and carnations
        if cat == "favorite drink":
            if asg[h].get("hobby") == "gardening" or asg[h].get("favorite flower") == "carnations":
                base_domain = [v for v in base_domain if v == "root beer"]
        if cat == "hobby":
            if asg[h].get("favorite drink") == "root beer" or asg[h].get("favorite flower") == "carnations":
                base_domain = [v for v in base_domain if v == "gardening"]
        if cat == "favorite flower":
            if asg[h].get("favorite drink") == "root beer" or asg[h].get("hobby") == "gardening":
                base_domain = [v for v in base_domain if v == "carnations"]

        # 3. green <-> coffee
        if cat == "favorite color":
            if asg[h].get("favorite drink") == "coffee" or asg[h].get("favorite flower") == "lilies":
                base_domain = [v for v in base_domain if v == "green"]
        if cat == "favorite drink":
            if asg[h].get("favorite color") == "green" or asg[h].get("favorite flower") == "lilies":
                base_domain = [v for v in base_domain if v == "coffee"]
        if cat == "favorite flower":
            if asg[h].get("favorite color") == "green" or asg[h].get("favorite drink") == "coffee":
                base_domain = [v for v in base_domain if v == "lilies"]

        # 6. cooking == blue
        if cat == "hobby":
            if asg[h].get("favorite color") == "blue":
                base_domain = [v for v in base_domain if v == "cooking"]
        if cat == "favorite color":
            if asg[h].get("hobby") == "cooking":
                base_domain = [v for v in base_domain if v == "blue"]

        # 9. Arnold == photography
        if cat == "Name":
            if asg[h].get("hobby") == "photography":
                base_domain = [v for v in base_domain if v == "Arnold"]
        if cat == "hobby":
            if asg[h].get("Name") == "Arnold":
                base_domain = [v for v in base_domain if v == "photography"]

        # 8. Peter == water
        if cat == "Name":
            if asg[h].get("favorite drink") == "water":
                base_domain = [v for v in base_domain if v == "Peter"]
        if cat == "favorite drink":
            if asg[h].get("Name") == "Peter":
                base_domain = [v for v in base_domain if v == "water"]

        # 10. white == roses
        if cat == "favorite color":
            if asg[h].get("favorite flower") == "roses":
                base_domain = [v for v in base_domain if v == "white"]
        if cat == "favorite flower":
            if asg[h].get("favorite color") == "white":
                base_domain = [v for v in base_domain if v == "roses"]

        # 7. Eric directly left of tea - prune impossible positions
        if cat == "Name":
            if "Eric" in base_domain:
                # Eric cannot be in house 5
                if h == 5:
                    base_domain = [v for v in base_domain if v != "Eric"]
                # If the drink on h+1 is assigned and not tea, Eric cannot be here
                if h < 5 and "favorite drink" in asg[h+1] and asg[h+1]["favorite drink"] != "tea":
                    base_domain = [v for v in base_domain if v != "Eric"]
        if cat == "favorite drink":
            if "tea" in base_domain:
                # Tea cannot be in house 1
                if h == 1:
                    base_domain = [v for v in base_domain if v != "tea"]
                # If the name on h-1 is assigned and not Eric, tea cannot be here
                if h > 1 and "Name" in asg[h-1] and asg[h-1]["Name"] != "Eric":
                    base_domain = [v for v in base_domain if v != "tea"]

        return base_domain

    def is_consistent(asg):
        # 1. Alice is not in the fourth house.
        if asg[4].get("Name") == "Alice":
            return False

        # 2 and 14. root beer <-> gardening and carnations
        for h in houses:
            d = asg[h].get("favorite drink")
            f = asg[h].get("favorite flower")
            hb = asg[h].get("hobby")
            if d == "root beer":
                if hb is not None and hb != "gardening":
                    return False
                if f is not None and f != "carnations":
                    return False
            if hb == "gardening":
                if d is not None and d != "root beer":
                    return False
                if f is not None and f != "carnations":
                    return False
            if f == "carnations":
                if d is not None and d != "root beer":
                    return False
                if hb is not None and hb != "gardening":
                    return False

        # 3. green <-> coffee
        for h in houses:
            c = asg[h].get("favorite color")
            d = asg[h].get("favorite drink")
            if c == "green" and d is not None and d != "coffee":
                return False
            if d == "coffee" and c is not None and c != "green":
                return False

        # 4. green <-> lilies
        for h in houses:
            c = asg[h].get("favorite color")
            f = asg[h].get("favorite flower")
            if c == "green" and f is not None and f != "lilies":
                return False
            if f == "lilies" and c is not None and c != "green":
                return False

        # 5. blue is right of daffodils
        hb = house_of("favorite color", "blue", asg)
        hdaf = house_of("favorite flower", "daffodils", asg)
        if hb is not None and hdaf is not None:
            if not (hb > hdaf):
                return False

        # 6. cooking == blue
        for h in houses:
            c = asg[h].get("favorite color")
            hbby = asg[h].get("hobby")
            if c == "blue" and hbby is not None and hbby != "cooking":
                return False
            if hbby == "cooking" and c is not None and c != "blue":
                return False

        # 7. Eric directly left of the tea drinker
        hEric = house_of("Name", "Eric", asg)
        hTea = house_of("favorite drink", "tea", asg)
        if hEric is not None and hTea is not None:
            if hTea != hEric + 1:
                return False
        else:
            # Partial pruning
            if hEric is not None:
                if hEric == 5:
                    return False
                # If right neighbor's drink assigned and not tea -> impossible
                if "favorite drink" in asg[hEric+1] and asg[hEric+1]["favorite drink"] != "tea":
                    return False
            if hTea is not None:
                if hTea == 1:
                    return False
                # If left neighbor's name assigned and not Eric -> impossible
                if "Name" in asg[hTea-1] and asg[hTea-1]["Name"] != "Eric":
                    return False

        # 8. Water is Peter (enforced partly by pre-assignments)
        for h in houses:
            if asg[h].get("favorite drink") == "water":
                if asg[h].get("Name") is not None and asg[h].get("Name") != "Peter":
                    return False
            if asg[h].get("Name") == "Peter":
                if asg[h].get("favorite drink") is not None and asg[h].get("favorite drink") != "water":
                    return False

        # 9. Arnold is the photography enthusiast.
        for h in houses:
            if asg[h].get("Name") == "Arnold":
                if asg[h].get("hobby") is not None and asg[h].get("hobby") != "photography":
                    return False
            if asg[h].get("hobby") == "photography":
                if asg[h].get("Name") is not None and asg[h].get("Name") != "Arnold":
                    return False

        # 10. white == roses (pre-assigned for house 2, ensure general consistency)
        for h in houses:
            if asg[h].get("favorite color") == "white":
                if asg[h].get("favorite flower") is not None and asg[h].get("favorite flower") != "roses":
                    return False
            if asg[h].get("favorite flower") == "roses":
                if asg[h].get("favorite color") is not None and asg[h].get("favorite color") != "white":
                    return False

        # 11. One house between carnations and red (difference 2)
        hRed = house_of("favorite color", "red", asg)
        hCarn = house_of("favorite flower", "carnations", asg)
        if hRed is not None and hCarn is not None:
            if abs(hRed - hCarn) != 2:
                return False
        else:
            # Partial pruning: if one is set and the other is set to an impossible house
            pass

        # 12. cooking left of painting
        hCook = house_of("hobby", "cooking", asg)
        hPaint = house_of("hobby", "painting", asg)
        if hCook is not None and hPaint is not None:
            if not (hCook < hPaint):
                return False
        else:
            if hCook is not None and hCook == 5:
                return False
            if hPaint is not None and hPaint == 1:
                return False

        # 13. water is in the third house (enforced)
        if asg[3].get("favorite drink") not in (None, "water"):
            return False
        # No other house should be water
        for h in houses:
            if h != 3 and asg[h].get("favorite drink") == "water":
                return False

        # 15. white is in the second house (enforced)
        if asg[2].get("favorite color") not in (None, "white"):
            return False
        for h in houses:
            if h != 2 and asg[h].get("favorite color") == "white":
                return False

        return True

    def select_unassigned(asg, usd):
        # MRV heuristic: pick the (house, category) with the smallest domain
        best = None
        best_domain = None
        for h in houses:
            for cat in categories:
                if cat not in asg[h]:
                    dom = possible_values(h, cat, asg, usd)
                    if best is None or len(dom) < len(best_domain):
                        best = (h, cat)
                        best_domain = dom
                        if len(best_domain) == 0:
                            return best, best_domain
        return best, best_domain

    def backtrack(asg, usd):
        # Check if assignment complete
        complete = True
        for h in houses:
            if len(asg[h]) != len(categories):
                complete = False
                break
        if complete:
            return asg

        (h, cat), dom = select_unassigned(asg, usd)
        if dom is None or len(dom) == 0:
            return None

        for val in dom:
            add_assignment(h, cat, val, asg, usd)
            if is_consistent(asg):
                result = backtrack(asg, usd)
                if result is not None:
                    return result
            remove_assignment(h, cat, val, asg, usd)
        return None

    solution = backtrack(assignment, used)
    return solution

def format_solution(solution):
    header = ["House", "Name", "favorite drink", "favorite color", "favorite flower", "hobby"]
    rows = []
    for h in [1, 2, 3, 4, 5]:
        row = [
            str(h),
            solution[h]["Name"],
            solution[h]["favorite drink"],
            solution[h]["favorite color"],
            solution[h]["favorite flower"],
            solution[h]["hobby"],
        ]
        rows.append(row)
    return {"solution": {"header": header, "rows": rows}}

def main():
    sol = solve_puzzle()
    output = format_solution(sol)
    print(json.dumps(output, indent=2))

if __name__ == "__main__":
    main()
